function validate([arr]) {
  const n = arr.length;
  if (n < 3 || n > 1000) return 'arr needs 3 to 1000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each value is an integer from 0 to 100000.';
  const total = arr[n - 1] - arr[0];
  const message = 'arr must be an arithmetic progression with exactly one inner value removed.';
  if (total % n !== 0) return message;
  const step = total / n;
  let doubled = 0;
  for (let i = 1; i < n; i++) {
    const gap = arr[i] - arr[i - 1];
    if (gap === step) continue;
    if (step !== 0 && gap === 2 * step && doubled === 0) { doubled++; continue; }
    return message;
  }
  return null;
}

