function missingNumber(arr) {
  const n = arr.length;
  const first = arr[0];
  const last = arr[n - 1];
  const expectedSum = ((first + last) * (n + 1)) / 2;
  let actualSum = 0;
  for (const value of arr) {
    actualSum += value;
  }
  return expectedSum - actualSum;
}

