  const step = (arr[arr.length - 1] - arr[0]) / arr.length;
  for (let i = 0; i < arr.length; i++) {
    const wanted = arr[0] + i * step;
    if (arr[i] !== wanted) return wanted;
  }
  // A zero step leaves every element equal, so the removed one matches them.
  return arr[0];
