function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(900, 1000) : int(3, 8);
  const limit = size === 'large' ? 100 : 6;
  const step = rand() < 0.15 ? 0 : int(-limit, limit);
  // Keep every term of the full progression (n + 1 terms) inside 0..100000.
  const span = Math.abs(step) * n;
  const first = (step >= 0 ? 0 : span) + int(0, size === 'large' ? 100000 - span : 30);
  const full = Array.from({ length: n + 1 }, (_, i) => first + i * step);
  const removed = int(1, n - 1);
  full.splice(removed, 1);
  return [full];
}
